import{_ as t,o,c as n,ah as a}from"./chunks/framework.ChH6X6u6.js";const u=JSON.parse('{"title":"Document management","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/gestion-documentaire/index.md","filePath":"src/en/guide/gestion-documentaire/index.md"}'),s={name:"en/guide/gestion-documentaire/index.md"};function i(r,e,d,h,c,l){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="document-management" tabindex="-1">Document management <a class="header-anchor" href="#document-management" aria-label="Permalink to &quot;Document management&quot;">​</a></h1><p>The <strong>Document management</strong> module files the school&#39;s documents in files: one per student, one per employee, and the school&#39;s own (minutes, regulations…). Each document is filed under a <strong>type</strong> of the catalogue (birth certificate, medical record, employment contract…), which decides who may consult it and who may validate it.</p><p>The <strong>Document manager</strong> is the profile dedicated to this module: they file, sort and check documents, and keep the catalogue of types. They have no access to any academic feature (grades, report cards, payments). Other profiles use the module too, each for the types that concern them: the office for enrollment papers, the infirmary for medical records, the cashier for invoices and receipts. The pages of the <strong>Documents</strong> space only show each person the types open to them.</p><div class="info custom-block"><p class="custom-block-title">Licensed module</p><p>The <strong>Documents</strong> space only appears if the school has activated the Document management module.</p></div><h2 id="the-documents-page" tabindex="-1">The Documents page <a class="header-anchor" href="#the-documents-page" aria-label="Permalink to &quot;The Documents page&quot;">​</a></h2><p>The <strong>Documents</strong> page brings two things together:</p><ul><li><strong>Open a file</strong>: type the name of a student or an employee, then click <strong>Search</strong>. Click a person to open their file. Only people for whom you can consult at least one document type are offered.</li><li><strong>Filed documents</strong>: the list of documents, filtered by default on those <strong>To check</strong> (submitted or being checked). Change the filter to see validated, rejected or all documents; pick a type to see only that one. The <strong>Search the documents</strong> field finds a document by its title, file name, notes or the text read on its pages (see <a href="/era-guide/en/guide/gestion-documentaire/numerisation.html">Digitisation</a>). Each row shows the type and the person concerned: click their name to open their file.</li></ul><p>The <strong>School documents</strong> button opens the school&#39;s own file, when you consult at least one type filed there.</p><h2 id="a-person-s-file" tabindex="-1">A person&#39;s file <a class="header-anchor" href="#a-person-s-file" aria-label="Permalink to &quot;A person&#39;s file&quot;">​</a></h2><p>The file lists, type by type, every document type you may consult for this person, with the documents filed under each. A type with no document shows <strong>No document</strong>: what is missing shows as plainly as what is there. The top of the page says how many types still have no document.</p><p>An administrator also opens this file from a student&#39;s or an employee&#39;s record, with the <strong>Document file</strong> button.</p><h2 id="files-from-the-other-modules" tabindex="-1">Files from the other modules <a class="header-anchor" href="#files-from-the-other-modules" aria-label="Permalink to &quot;Files from the other modules {#files-from-the-other-modules}&quot;">​</a></h2><p>The file also shows, under their type, the files the other ERA modules already keep, without moving or copying them:</p><table tabindex="0"><thead><tr><th>File</th><th>Document type</th><th>File</th></tr></thead><tbody><tr><td>Papers attached to an approved application</td><td>Application file</td><td>Student</td></tr><tr><td>Published report cards</td><td>Report card</td><td>Student</td></tr><tr><td>Payment receipts</td><td>Invoice or receipt</td><td>Student</td></tr><tr><td>Absence justifications sent in</td><td>Absence justification</td><td>Student</td></tr><tr><td>Disciplinary council minutes</td><td>Disciplinary council minutes</td><td>Student</td></tr><tr><td>Published transcripts (higher education)</td><td>Transcript</td><td>Student</td></tr><tr><td>Certificates of completion (higher education)</td><td>Certificate</td><td>Student</td></tr><tr><td>Employment contracts attached to the record</td><td>Employment contract</td><td>Employee</td></tr><tr><td>Supporting documents attached to expenses</td><td>Expense receipt</td><td>School</td></tr></tbody></table><p>These files carry the label of the module that keeps them (<strong>Report cards</strong>, <strong>Cashier</strong>, <strong>School life</strong>…) and an <strong>Open</strong> button. They are not checked: they are managed from their module, as before. Transcripts and certificates are produced when you open them, from what the jury published.</p><p>Who sees them depends on their type in the catalogue: for example, by default, the office sees report cards and receipts, but not disciplinary council minutes, which are kept for the document manager and school life. If the school deletes one of these types, its files no longer appear in the files.</p><h2 id="file-a-document" tabindex="-1">File a document <a class="header-anchor" href="#file-a-document" aria-label="Permalink to &quot;File a document&quot;">​</a></h2><ol><li>In the file, click <strong>File</strong> next to the type concerned.</li><li>Choose the <strong>File</strong>: a PDF or an image (JPG, PNG, WebP), 10 MB at most. For a paper you have at hand, choose <strong>Photos of the pages</strong> instead and photograph it with a phone: see <a href="/era-guide/en/guide/gestion-documentaire/numerisation.html">Digitisation</a>.</li><li>If needed, fill in a <strong>Title</strong> (for example &quot;Birth certificate no. 1234&quot;), the <strong>Date of the document</strong> (the one it carries) and <strong>Notes</strong>.</li><li>If you may validate this type, the <strong>I have checked it: validate it now</strong> box is ticked: the document is validated as soon as it is filed. This is the usual case at the desk, with the original in front of you. Untick it to leave it to be checked.</li><li>Click <strong>File</strong>.</li></ol><h2 id="check-a-document" tabindex="-1">Check a document <a class="header-anchor" href="#check-a-document" aria-label="Permalink to &quot;Check a document&quot;">​</a></h2><p>A filed document goes through these statuses:</p><table tabindex="0"><thead><tr><th>Status</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Submitted</strong></td><td>The document is waiting to be checked</td></tr><tr><td><strong>Being checked</strong></td><td>Someone has taken it in hand: others see it is in progress</td></tr><tr><td><strong>Validated</strong></td><td>The document has been checked and accepted</td></tr><tr><td><strong>Rejected</strong></td><td>The document was refused; the reason is shown, so it can be handed in again</td></tr></tbody></table><p>If you may validate the type, each pending document offers:</p><ul><li><strong>Open</strong> — shows the file in a new tab;</li><li><strong>Take in hand</strong> — moves it to <strong>Being checked</strong> under your name;</li><li><strong>Validate</strong> — accepts it;</li><li><strong>Reject</strong> — refuses it: give the <strong>reason for rejection</strong>, which is required. It stays displayed under the document.</li></ul><p>The <a href="/era-guide/en/guide/prise-en-main.html">dashboard</a> shows how many documents are waiting for your check, for the types you may validate only.</p><p>Once validated or rejected, a document&#39;s status no longer changes. To replace a rejected document, file a new one.</p><h2 id="delete-a-document" tabindex="-1">Delete a document <a class="header-anchor" href="#delete-a-document" aria-label="Permalink to &quot;Delete a document&quot;">​</a></h2><p>An administrator or the document manager may delete any document they consult. Whoever filed a document may withdraw it as long as nobody has taken it in hand. Deleting removes the file for good and is recorded in the activity log.</p><h2 id="confidential-documents" tabindex="-1">Confidential documents <a class="header-anchor" href="#confidential-documents" aria-label="Permalink to &quot;Confidential documents&quot;">​</a></h2><p>A type marked <strong>Confidential</strong> (the medical record and the employment contract at the start) is only open to the profiles its type names. Each time someone opens one of its documents, ERA records it in the <a href="/era-guide/en/guide/admin/demo-et-journal.html">activity log</a> with the <strong>Viewed</strong> action, the person and the address they opened it from.</p><p>To set who consults and validates each type, see <a href="/era-guide/en/guide/gestion-documentaire/types-de-documents.html">Document types</a>.</p>',30)])])}const p=t(s,[["render",i]]);export{u as __pageData,p as default};
